CREATE TABLE bm_compute_data_asset (
 asset_code VARCHAR(64) PRIMARY KEY, name VARCHAR(128) NOT NULL, owner VARCHAR(128) NOT NULL,
 source_kind VARCHAR(24) NOT NULL, authoritative_source VARCHAR(128) NOT NULL,
 update_requirement VARCHAR(512) NOT NULL, max_age_seconds INT NULL,
 sensitivity VARCHAR(16) NOT NULL, quality_requirement VARCHAR(512) NOT NULL,
 fields_json JSON NOT NULL, version INT NOT NULL DEFAULT 1,
 updated_by VARCHAR(64) NOT NULL, updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 CHECK(source_kind IN ('SIMULATED','PLATFORM','EXTERNAL_PENDING','CONNECTED')),
 CHECK(sensitivity IN ('PUBLIC','INTERNAL','SENSITIVE')), CHECK(max_age_seconds IS NULL OR max_age_seconds>0)
);
INSERT INTO bm_compute_data_asset(asset_code,name,owner,source_kind,authoritative_source,update_requirement,max_age_seconds,sensitivity,quality_requirement,fields_json,updated_by) VALUES('GPU_OBSERVATION','GPU 占用与利用率','运维','SIMULATED','A800_DEMO_FIXTURE','秒级采集；有效期与最大年龄分别检查，当前 30 秒教学样例','30','INTERNAL','监控提供物理状态；平台持有账本不能被监控覆盖','[{"table": "gpu_device", "column": "id", "meaning": "数据库稳定编号", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "node_id", "meaning": "所属节点编号", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "group_id", "meaning": "卡组编号，分配与持有以整组为单位", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "gpu_uuid", "meaning": "GPU 稳定 UUID", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "gpu_index", "meaning": "节点内本地卡号，须同时提供节点编号", "dataType": "SMALLINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "model", "meaning": "model：GPU 占用与利用率登记字段，结合本体属性映射解释", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "gpu_device", "column": "vram_bytes", "meaning": "vram_bytes：字节，非负整数，所有计算使用同一单位", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": "bytes", "states": {}}, {"table": "resource_observation", "column": "id", "meaning": "数据库稳定编号", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "node_id", "meaning": "所属节点编号", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "source_subject_kind", "meaning": "采集端主体类型", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "source_subject_key", "meaning": "采集端主体稳定标识", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "subject_kind", "meaning": "已对齐的主体类型", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "subject_id", "meaning": "subject_id：关联对象稳定编号，受外键约束", "dataType": "BIGINT", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "source", "meaning": "数据生产来源", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}, {"table": "resource_observation", "column": "observed_at", "meaning": "采集时间（UTC）", "dataType": "DATETIME", "sensitivity": "INTERNAL", "unit": "UTC", "states": {}}, {"table": "resource_observation", "column": "received_at", "meaning": "服务端接收时间（UTC）", "dataType": "DATETIME", "sensitivity": "INTERNAL", "unit": "UTC", "states": {}}, {"table": "resource_observation", "column": "valid_until", "meaning": "观测有效截止时间（UTC）", "dataType": "DATETIME", "sensitivity": "INTERNAL", "unit": "UTC", "states": {}}, {"table": "resource_observation", "column": "status", "meaning": "生命周期状态，参见状态值定义", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {"OK": "采集成功，仍需检查时效和字段", "ERROR": "采集失败，不能补零或冒充最新成功"}}, {"table": "resource_observation", "column": "values_json", "meaning": "values_json：GPU 占用与利用率登记字段，结合本体属性映射解释", "dataType": "JSON", "sensitivity": "SENSITIVE", "unit": null, "states": {}}, {"table": "resource_observation", "column": "error_detail", "meaning": "error_detail：GPU 占用与利用率登记字段，结合本体属性映射解释", "dataType": "VARCHAR", "sensitivity": "INTERNAL", "unit": null, "states": {}}]','compute-m05-migration');
